# 花香与珠光 · 游戏 3 号

本关使用「花香与珠光-分割 2 号素材包」的完整独立 PNG 与原场景遮挡部件，面向微信小游戏和 Cocos Creator 3.8.x App 接入。原素材包由上级交付保留，运行目录使用其派生资源副本。

`data/fragrance-pearl-layout.json` 是共享关卡，`src/core/` 负责逐区与 L1 → L2 → L3 拼装进度，`src/rendering/` 是平台无关 Canvas 游戏，`src/adapters/wechat/` 与 `src/adapters/cocos/` 分别接入微信和原生引擎。完整贴纸拿起、左向右压平、金色完成动效、区域自动巡游、撤销与 JSON 微调共用关卡数据。

在项目安装依赖后执行 `npm run build`，再执行 `npm test`。当前工作区构建器也可读取已安装的共享 TypeScript 和官方 cc 声明，不复制 node_modules。外部环境可通过 `FRAGRANCE_TYPESCRIPT_PATH` 和 `FRAGRANCE_COCOS_TYPES_PATH` 指定已安装工具的绝对路径。

构建生成 `preview/runtime.js`、`preview/layout.js`、旁边可离线打开的 `花香与珠光-交互验证.html`、微信 `wechat/` 和原生 `cocos-import/`。微信资源采用 canonical assetKey → 实体子包路径映射，按实际字节分桶，避免整目录堆入一个超大分包。打开微信开发者工具时导入 `wechat/`，填写自己的 AppID；源码构建不提交上传，也不生成商店安装包。

本关源可见覆盖只在原组装位置、尺寸、角度、锚点与遮挡队列保持一致时使用。微调后改为完整单件，纸栏预览始终显示完整 canonical PNG。完整源素材和游戏状态分离保存，微调只改变 JSON 参数。

查看 `docs/build-report.json` 与 `tests/session-check-results.json` 获取实际检查结果。Cocos 组件的详细导入路径与纹理要求见 `src/adapters/cocos/COCOS接入.md`。编辑器、微信开发者工具和真机验收状态以报告为准，源码检查不能替代设备验收。
<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>花香与珠光 · 交互验证</title>
<style>html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#faf5e9;touch-action:none}canvas{display:block;width:100%;height:100%}#failure{display:none;position:fixed;inset:35% 20px auto;color:#5b3531;font:14px sans-serif;text-align:center}#toast{position:fixed;left:50%;bottom:28px;transform:translateX(-50%);background:#492c2ce8;color:#fff4df;padding:12px 18px;border-radius:12px;font:13px sans-serif;max-width:80%;pointer-events:none;opacity:0}</style></head>
<body><canvas id="game" aria-label="花香与珠光贴纸交互验证"></canvas><div id="failure"></div><div id="toast"></div>
<script src="layout.js"></script><script src="runtime.js"></script>
<script>
const canvas=document.getElementById('game');
const toast=message=>{const t=document.getElementById('toast');t.textContent=message;t.style.opacity=1;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.opacity=0,2600)};
const download=(url,name)=>{const a=document.createElement('a');a.href=url;a.download=name;a.click()};
const platform={
createCanvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c},
loadImage(key){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('图片加载失败: '+key));i.src=window.FRAGRANCE_ASSETS?.[key]||'../'+key})},
storage:{get(key){try{return JSON.parse(localStorage.getItem('fragrance-pearl-preview:'+key))}catch{return null}},set(key,value){localStorage.setItem('fragrance-pearl-preview:'+key,JSON.stringify(value))},remove(key){localStorage.removeItem('fragrance-pearl-preview:'+key)}},
now:()=>performance.now(),requestFrame:cb=>requestAnimationFrame(cb),cancelFrame:id=>cancelAnimationFrame(id),toast,
confirm:async message=>confirm(message),
importJson:()=>new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>resolve(input.files[0]?await input.files[0].text():null);input.oncancel=()=>resolve(null);input.click()}),
exportJson:async text=>{const u=URL.createObjectURL(new Blob([text],{type:'application/json'}));download(u,'花香与珠光-手动排布.json');setTimeout(()=>URL.revokeObjectURL(u),1000)},
exportImage:async image=>{download(image.toDataURL('image/png'),'花香与珠光-完成图.png')}
};
const game=new FragranceCanvas({canvas,layout:window.FRAGRANCE_LAYOUT,platform});window.fragranceGame=game;
const resize=()=>game.resize(innerWidth,innerHeight,devicePixelRatio||1,{left:0,top:0,right:innerWidth,bottom:innerHeight});resize();addEventListener('resize',resize);
canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);game.pointerDown(e.clientX,e.clientY,e.pointerId)});
canvas.addEventListener('pointermove',e=>game.pointerMove(e.clientX,e.clientY,e.pointerId));
canvas.addEventListener('pointerup',e=>game.pointerUp(e.clientX,e.clientY,e.pointerId));
canvas.addEventListener('pointercancel',e=>game.pointerCancel(e.pointerId));
document.addEventListener('visibilitychange',()=>document.hidden?game.suspend():game.resume());
game.start().catch(error=>{const f=document.getElementById('failure');f.style.display='block';f.textContent=error.message;console.error(error)});
</script></body></html>
import { GameLayout, RenderPart, StickerPlacement, renderEntryKey } from './GameSession';

const samePoint = (a: { x: number; y: number }, b: { x: number; y: number }): boolean =>
  a.x === b.x && a.y === b.y;

/** Source masks are tied to the original assembly pose and painter queue.
 * Once an object moves, changes scale/rotation/anchor or layer, draw one complete
 * canonical object. The immutable source controls this choice; imported flags
 * cannot re-enable a source-visible overlay on a changed object.
 */
export function assemblyRenderParts(layout: GameLayout, sourceLayout: GameLayout): Map<string, RenderPart[]> {
  const originals = new Map(sourceLayout.stickers.map(owner => [owner.stickerId, owner]));
  const ranks = (value: GameLayout) => new Map([...(value.renderOrder ?? [])]
    .sort((a, b) => a.placementOrder - b.placementOrder)
    .map((entry, index) => [renderEntryKey(entry), index]));
  const currentRanks = ranks(layout), sourceRanks = ranks(sourceLayout);
  const result = new Map<string, RenderPart[]>();
  for (const owner of layout.stickers) {
    const original = originals.get(owner.stickerId);
    const sourceParts = new Map((original?.renderParts ?? []).map(part => [part.partId, part]));
    const atSource = !!original && samePoint(owner.position, original.position)
      && samePoint(owner.anchor, original.anchor) && owner.scale === original.scale
      && owner.rotation === original.rotation && owner.layerIndex === original.layerIndex
      && (owner.renderParts ?? []).length === sourceParts.size
      && (owner.renderParts ?? []).every(part => {
        const source = sourceParts.get(part.partId);
        return !!source && source.layerIndex === part.layerIndex
          && currentRanks.get(`stickerPart:${part.partId}`) === sourceRanks.get(`stickerPart:${part.partId}`);
      });
    if (atSource) { result.set(owner.stickerId, [...(owner.renderParts ?? [])]); continue; }
    // Keep an existing queue identity, so changing a pose never invents a layer.
    const fallback = (owner.renderParts ?? []).find(part => {
      const source = sourceParts.get(part.partId);
      return source?.fullAssetKey && !source.assemblyOnly;
    }) ?? (owner.renderParts ?? []).find(part => !sourceParts.get(part.partId)?.assemblyOnly)
      ?? owner.renderParts?.[0];
    result.set(owner.stickerId, fallback && original ? [{ ...fallback,
      assetKey: original.assetKey, file: original.assetKey,
      sourceSize: { ...owner.sourceSize }, offset: { x: 0, y: 0 },
      requiresAssetIds: [], assemblyOnly: false,
    }] : []);
  }
  return result;
}

export function stickerAssemblyRenderParts(layout: GameLayout, sourceLayout: GameLayout,
  owner: StickerPlacement): RenderPart[] {
  return assemblyRenderParts(layout, sourceLayout).get(owner.stickerId) ?? [];
}

